INSERT INTO `chat_messages` VALUES (1,1,'user','SH 160i giá bao nhiêu vậy shop?',1,'2026-10-13 08:00:10'),(2,1,'user','Giá vốn SH 160i của shop là bao nhiêu?',8,'2026-10-13 08:01:00'),(3,2,'user','Đơn hàng của mình đến đâu rồi?',4,'2026-10-13 08:10:20'),(4,3,'user','Chiết khấu tối đa cho khách mua Vision là bao nhiêu?',6,'2026-10-13 08:20:15'),(5,3,'user','Mẫu SH 160i còn hàng ở chi nhánh 2 không?',3,'2026-10-13 08:21:00'),(6,4,'user','Cách đọc mã lỗi PGM-FI trên Air Blade?',7,'2026-10-13 08:30:30'),(7,4,'user','Giá vốn của Air Blade 160?',8,'2026-10-13 08:31:00'),(8,7,'user','SH 160i giá bao nhiêu?',NULL,'2026-10-14 08:51:43'),(9,7,'bot','Tìm thấy 3 bản ghi:\nproduct_id: 8 | model_name: SH 160i | variant_id: 20 | variant_name: SH 160i - Tiêu chuẩn - Xám | color: Xám | segment: tay_ga | engine_cc: 157 | list_price: 92500000 | total_stock: 16 | fuel_consumption_l100km: 2.3 | description: Tay ga cao cấp, phanh ABS, khóa thông minh. | engine_type: 4 thì, 1 xy-lanh, làm mát bằng dung dịch | fuel_tank_l: 7.8 | weight_kg: 134 | brake_type: Đĩa trước / Đĩa sau, ABS | warranty: 3 năm hoặc 30.000 km\nproduct_id: 8 | model_name: SH 160i | variant_id: 21 | variant_name: SH 160i - Cao cấp - Đen | color: Đen | segment: tay_ga | engine_cc: 157 | list_price: 96500000 | total_stock: 10 | fuel_consumption_l100km: 2.3 | description: Tay ga cao cấp, phanh ABS, khóa thông minh. | engine_type: 4 thì, 1 xy-lanh, làm mát bằng dung dịch | fuel_tank_l: 7.8 | weight_kg: 134 | brake_type: Đĩa trước / Đĩa sau, ABS | warranty: 3 năm hoặc 30.000 km\nproduct_id: 8 | model_name: SH 160i | variant_id: 22 | variant_name: SH 160i - Thể thao - Đỏ đen | color: Đỏ đen | segment: tay_ga | engine_cc: 157 | list_price: 100500000 | total_stock: 27 | fuel_consumption_l100km: 2.3 | description: Tay ga cao cấp, phanh ABS, khóa thông minh. | engine_type: 4 thì, 1 xy-lanh, làm mát bằng dung dịch | fuel_tank_l: 7.8 | weight_kg: 134 | brake_type: Đĩa trước / Đĩa sau, ABS | warranty: 3 năm hoặc 30.000 km',NULL,'202