CREATE TABLE `chatbot_audit_log` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `session_id` int(11) NOT NULL,
  `user_id` int(11) DEFAULT NULL,
  `intent_id` int(11) DEFAULT NULL,
  `decision` enum('allowed','denied') NOT NULL,
  `reason` varchar(255) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `session_id` (`session_id`),
  KEY `intent_id` (`intent_id`),
  CONSTRAINT `chatbot_audit_log_ibfk_1` FOREIGN KEY (`session_id`) REFERENCES `chat_sessions` (`id`),
  CONSTRAINT `chatbot_audit_log_ibfk_2` FOREIGN KEY (`intent_id`) REFERENCES `chatbot_intents` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1964 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
