/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `customer_input_batches` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `created_by` int(11) NOT NULL,
  `document_id` bigint(20) DEFAULT NULL,
  `chat_session_id` int(11) DEFAULT NULL,
  `status` enum('draft','committed','cancelled') NOT NULL DEFAULT 'draft',
  `rows_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`rows_json`)),
  `preview_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`preview_json`)),
  `result_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`result_json`)),
  `version` int(11) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `document_id` (`document_id`),
  KEY `chat_session_id` (`chat_session_id`),
  KEY `ix_customer_batch_owner` (`created_by`,`status`),
  CONSTRAINT `customer_input_batches_ibfk_1` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`),
  CONSTRAINT `customer_input_batches_ibfk_2` FOREIGN KEY (`document_id`) REFERENCES `document_uploads` (`id`),
  CONSTRAINT `customer_input_batches_ibfk_3` FOREIGN KEY (`chat_session_id`) REFERENCES `chat_sessions` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=431 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
