--
-- Table structure for table `customer_profiles`
--

DROP TABLE IF EXISTS `customer_profiles`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `customer_profiles` (
  `user_id` int(11) NOT NULL,
  `customer_code` varchar(20) NOT NULL,
  `gender` enum('Nam','Nữ') DEFAULT NULL,
  `birth_date` date DEFAULT NULL,
  `province` varchar(60) DEFAULT NULL,
  `district` varchar(80) DEFAULT NULL,
  `address` varchar(255) DEFAULT NULL,
  `occupation` varchar(100) DEFAULT NULL,
  `lead_source` varchar(60) DEFAULT NULL,
  `interested_product_id` int(11) DEFAULT NULL,
  `payment_preference` enum('Trả thẳng','Trả góp') DEFAULT NULL,
  `registered_at` date DEFAULT NULL,
  `status` enum('Tiềm năng','Đang tư vấn','Đã mua','Ngừng liên hệ') DEFAULT NULL,
  PRIMARY KEY (`user_id`),
  UNIQUE KEY `customer_code` (`customer_code`),
  KEY `interested_product_id` (`interested_product_id`),
  CONSTRAINT `customer_profiles_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `customer_profiles_ibfk_2` FOREIGN KEY (`interested_product_id`) REFERENCES `products` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

