  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `uploaded_by` int(11) NOT NULL,
  `category_id` int(11) NOT NULL,
  `branch_id` int(11) DEFAULT NULL,
  `title` varchar(255) NOT NULL,
  `original_name` varchar(255) NOT NULL,
  `stored_name` varchar(80) NOT NULL,
  `file_format` varchar(10) NOT NULL,
  `size_bytes` int(11) NOT NULL,
  `sha256` char(64) NOT NULL,
  `status` enum('uploaded','processing','ready','needs_review','failed','published') NOT NULL DEFAULT 'uploaded',
  `result_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`result_json`)),
  `review_content` longtext DEFAULT NULL,
  `review_notes` text DEFAULT NULL,
  `error_code` varchar(60) DEFAULT NULL,
  `error_message` varchar(500) DEFAULT NULL,
  `reviewed_by` int(11) DEFAULT NULL,
  `reviewed_at` datetime DEFAULT NULL,
  `published_doc_id` int(11) DEFAULT NULL,
  `version` int(11) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `processing_started_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_document_owner` (`uploaded_by`,`created_at`),
  KEY `ix_document_branch` (`branch_id`,`status`),
  KEY `category_id` (`category_id`),
  KEY `reviewed_by` (`reviewed_by`),
  KEY `published_doc_id` (`published_doc_id`),
  CONSTRAINT `document_uploads_ibfk_1` FOREIGN KEY (`uploaded_by`) REFERENCES `users` (`id`),
  CONSTRAINT `document_uploads_ibfk_2` FOREIGN KEY (`category_id`) REFERENCES `kb_categories` (`id`),
  CONSTRAINT `document_uploads_ibfk_3` FOREIGN KEY (`branch_id`) REFERENCES `branches` (`id`),
  CONSTRAINT `document_uploads_ibfk_4` FOREIGN KEY (`reviewed_by`) REFERENCES `users` (`id`),
  CONSTRAINT `document_uploads_ibfk_5` FOREIGN KEY (`published_doc_id`) REFERENCES `kb_documents` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=290 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Tài liệu tải lên và bản nháp trích xuất; chỉ bản đã duyệt mới vào kho tri thức';
/*!40101 SET character_set_client = @saved_cs_client */;

